    private int quantity;
    private double price;

    public OrderItem(String name, int quantity, double price) {
        this.name = name;
        this.quantity = quantity;
        this.price = price;
    }
}

public enum OrderStatus {
    OPEN, PAID, SHIPPED, COMPLETED, CANCELED;
}

