public interface Authorizer {
    void verify_code(String code);
    boolean is_authenticated();
}

public class SMSAuthorizer implements Authorizer {
    private boolean authenticated;

    public SMSAuthorizer() {
        this.authenticated = false;
    }

    @Override
    public void verify_code(String code) {
        System.out.println("Verifying code");
        this.authenticated = true;
    }

    @Override
    public boolean is_authenticated() {
        return this.authenticated;
    }
}

public class DebitCardPaymentProcessor extends PaymentProcessor {
    private Authorizer authorizer;
    private String securityCode;

    public DebitCardPaymentProcessor(String securityCode, Authorizer authorizer) {
        this.authorizer = authorizer;
        this.securityCode = securityCode;
    }

    @Override
    public void pay(Order order) {
        if (!this.authorizer.is_authenticated()) {
            throw new IllegalStateException("Not authenticated");
        }
        System.out.println("Processing debit card payment");
        System.out.println("Verifying security code: " + this.securityCode);
        order.setStatus("paid");
    }
}
